<div class="page-head"><h1>Assignments and cohorts: <?= e($course['title']) ?></h1><p><a href="<?= e(url('/admin/courses')) ?>">Courses</a> · <a href="<?= e(url('/admin/gradebook/'.$course['slug'])) ?>">Gradebook</a> · <a href="<?= e(url('/assignments/'.$course['slug'])) ?>">Learner view</a></p></div>
<div class="card"><h2>Assignments</h2><?php if (!$assignments): ?><p>No submission assignments yet. Existing gradebook assessments remain unchanged.</p><?php endif; ?><ul><?php foreach ($assignments as $a): ?><li><a href="<?= e(url('/admin/assignment/'.$a['id'])) ?>"><?= e($a['title']) ?> — review submissions</a> · <?= !empty($a['required_completion'])?'Required':'Optional' ?></li><?php endforeach; ?></ul></div>
<div class="card"><h2>Add an assignment</h2><form method="post" action="<?= e(url('/admin/assignments/'.$course['slug'])) ?>"><?= csrf_field() ?><div class="field"><label for="title">Title</label><input id="title" name="title" maxlength="191" required></div><div class="field"><label for="instructions">Instructions</label><textarea id="instructions" name="instructions" rows="5" maxlength="50000" style="width:100%"></textarea></div><div class="field"><label for="rubric_id">Rubric</label><select id="rubric_id" name="rubric_id"><option value="0">Use a single points score</option><?php foreach ($rubrics as $r): ?><option value="<?= (int)$r['id'] ?>"><?= e($r['title']) ?></option><?php endforeach; ?></select><small>A rubric determines the maximum points and is copied into this assignment.</small></div><div class="field"><label for="max_points">Maximum points</label><input id="max_points" name="max_points" type="number" min="1" max="10000" step="0.01" value="100" required></div><div class="field"><label for="pass_percent">Passing percentage</label><input id="pass_percent" name="pass_percent" type="number" min="0" max="100" step="0.01" value="70" required></div><div class="field"><label for="available">Release date (optional, include timezone)</label><input id="available" name="available" placeholder="2026-10-01T09:00:00-05:00"></div><div class="field"><label for="due">Due date (optional, include timezone)</label><input id="due" name="due" placeholder="2026-10-15T17:00:00-05:00"></div><div class="field"><label for="late_policy">Late work</label><select id="late_policy" name="late_policy"><option value="accept">Accept and identify as late</option><option value="close">Close submissions after deadline</option></select></div><p><label><input type="checkbox" name="required"> Required for new course completion and certificate</label></p><p><label><input type="checkbox" name="resubmit" checked> Allow drafts and resubmissions after submission</label></p><p>Add required assignments before enrolling a cohort. Existing transcript credentials are retained.</p><button class="btn btn-gold" type="submit">Create assignment</button></form></div>
<div class="card"><h2>Save a reusable rubric</h2><form method="post" action="<?= e(url('/admin/assignments/'.$course['slug'].'/rubric')) ?>"><?= csrf_field() ?><div class="field"><label for="rubric-title">Rubric title</label><input id="rubric-title" name="title" required maxlength="191"></div><div class="field"><label for="criteria">Criteria, one per line: title | maximum points</label><textarea id="criteria" name="criteria" rows="4" style="width:100%" required placeholder="Application of learning | 60&#10;Reflection and evidence | 40"></textarea></div><button class="btn btn-outline" type="submit">Save rubric</button></form></div>
<div class="card"><h2>Cohort schedule</h2><p>Group schedules control course release and override assignment deadlines. For overlapping groups, the latest release, earliest deadline, and strictest late policy apply. All stored dates are UTC.</p><ul><?php foreach ($schedules as $s): ?><li><?= e($s['name']) ?>: opens <?= e($s['opens_at']?:'immediately') ?>; due <?= e($s['due_at']?:'assignment default') ?> UTC; <?= e($s['late_policy']) ?></li><?php endforeach; ?></ul><form method="post" action="<?= e(url('/admin/assignments/'.$course['slug'].'/schedule')) ?>"><?= csrf_field() ?><div class="field"><label for="group_id">Group</label><select id="group_id" name="group_id" required><?php foreach ($groups as $g): ?><option value="<?= (int)$g['id'] ?>"><?= e($g['name']) ?></option><?php endforeach; ?></select></div><div class="field"><label for="opens">Course release (include timezone)</label><input id="opens" name="opens" placeholder="2026-10-01T09:00:00-05:00"></div><div class="field"><label for="cohort-due">Assignment deadline (include timezone)</label><input id="cohort-due" name="due" placeholder="2026-10-15T17:00:00-05:00"></div><div class="field"><label for="cohort-late">Late work</label><select id="cohort-late" name="late_policy"><option value="accept">Accept</option><option value="close">Close</option></select></div><button class="btn btn-outline" type="submit">Save schedule</button></form></div>

<?php if (is_admin()): ?><div class="card"><h2>Course instructors</h2><p>Only administrators and explicitly assigned instructors can review learner submissions. Content-author access alone does not grant access to student work.</p><ul><?php foreach (db_all('SELECT u.email FROM users u JOIN course_instructors i ON i.user_id=u.id WHERE i.course_id=?',[$course['id']]) as $instructor): ?><li><?= e($instructor['email']) ?></li><?php endforeach; ?></ul><form method="post" action="<?= e(url('/admin/assignments/'.$course['slug'].'/instructor')) ?>"><?= csrf_field() ?><div class="field"><label for="instructor-email">Existing user's email</label><input id="instructor-email" name="email" type="email" required></div><button class="btn btn-outline" name="action" value="assign" type="submit">Assign instructor</button> <button class="btn btn-outline" name="action" value="remove" type="submit">Remove instructor</button></form></div><?php endif; ?>
